const pageJS = `var d=document,R=d.documentElement;R.classList.add('js');
function ancestors(t,fn){for(var p=t;p;p=p.parentElement)fn(p)}
d.addEventListener('click',function(e){var b=e.target.closest('button[data-copy]');if(b&&navigator.clipboard){navigator.clipboard.writeText(b.closest('.copybox').querySelector('pre').innerText).then(function(){var s=b.querySelector('span'),o=s.textContent;s.textContent=b.dataset.done;setTimeout(function(){s.textContent=o},1500)})}});
[].forEach.call(d.querySelectorAll('button[data-copy]'),function(b){b.hidden=false});
var F=[].slice.call(d.querySelectorAll('details[data-fold]'));F.forEach(function(x){x.open=false});
var W;addEventListener('beforeprint',function(){R.classList.add('printing');W=F.map(function(x){return x.open});F.forEach(function(x){x.open=true})});
addEventListener('afterprint',function(){R.classList.remove('printing');if(W)F.forEach(function(x,i){x.open=W[i]})});
var S=[].slice.call(d.querySelectorAll('.sec')),RM=matchMedia('(prefers-reduced-motion: reduce)'),DT=[].slice.call(d.querySelectorAll('.dots6 a'));
/* snapping rule (docs/24 §17.2): native CSS mandatory snap, only when every section fits the viewport,
   the viewport is at least 560px tall, and reduced motion is not requested. Otherwise plain scrolling. */
function fits(){var h=innerHeight;return S.every(function(s){return s.hidden||s.classList.contains('tall8')||s.getBoundingClientRect().height<=h+2})}/* tall8: reference sections may run longer than a screen; a snap area larger than the viewport scrolls freely inside (CSS Scroll Snap) */
function mode(){var on=!RM.matches&&innerHeight>=560&&!R.classList.contains('printing')&&fits();R.classList.toggle('snap',on);return on}
mode();addEventListener('resize',mode);if(RM.addEventListener)RM.addEventListener('change',mode);d.addEventListener('toggle',mode,true);
if(d.fonts&&d.fonts.ready)d.fonts.ready.then(mode);addEventListener('beforeprint',function(){R.classList.remove('snap')});addEventListener('afterprint',mode);
function cur(id){DT.forEach(function(a){if(a.getAttribute('href')==='#'+id)a.setAttribute('aria-current','step');else a.removeAttribute('aria-current')})}
if('IntersectionObserver' in window){var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting)cur(e.target.id)})},{threshold:.5});S.forEach(function(s){io.observe(s)})}
cur(S[0].id);
function CF(root){[].forEach.call(root.querySelectorAll('[data-cases]'),function(c){if(c.closest('.ev6')||c.getAttribute('data-ready'))return;c.setAttribute('data-ready','1');
var L=[].slice.call(c.querySelectorAll('.case')),i=0,pos=c.querySelector('.cpos'),pv=c.querySelector('.cprev'),nx=c.querySelector('.cnext'),fmt=c.getAttribute('data-fmt');
function show(k){i=Math.max(0,Math.min(L.length-1,k));L.forEach(function(x,j){x.classList.toggle('on',j===i)});if(pos)pos.textContent=fmt.replace('{i}',i+1).replace('{n}',L.length);if(pv)pv.disabled=i===0;if(nx)nx.disabled=i===L.length-1}
if(pv)pv.addEventListener('click',function(){show(i-1)});if(nx)nx.addEventListener('click',function(){show(i+1)});show(0)})}
CF(d);
var DL=d.getElementById('dlg6'),DB=DL.querySelector('.dlg-body'),DTT=DL.querySelector('.dlg-title'),DK=DL.querySelector('.dlg-kick'),opener;
function openEv(id,btn){var src=d.getElementById(id);if(!src||!DL.showModal)return false;DB.innerHTML=src.innerHTML;DTT.textContent=src.getAttribute('data-title');DK.textContent='';
CF(DB);opener=btn;R.classList.add('dlg');DL.showModal();DL.scrollTop=0;return true}
d.addEventListener('click',function(e){var b=e.target.closest('[data-ev]');if(b&&openEv(b.getAttribute('data-ev'),b))e.preventDefault()});
DL.addEventListener('close',function(){R.classList.remove('dlg');if(opener)setTimeout(function(){opener.focus()},0)});
DL.addEventListener('keydown',function(e){var b=e.key==='ArrowLeft'?DB.querySelector('.cprev'):e.key==='ArrowRight'?DB.querySelector('.cnext'):null;if(b&&!b.disabled){b.click();e.preventDefault()}});
DL.querySelector('.dlg-close').addEventListener('click',function(){DL.close()});
DL.addEventListener('click',function(e){if(e.target===DL)DL.close()});
`

